CREATE OR REPLACE FUNCTION calculate_composite_allocation_score(p_match_id text)
RETURNS numeric AS $$
DECLARE
    v_status_medical numeric;
    v_r_wait numeric;
    v_s_urgency numeric;
    v_i_abo numeric;
    v_hla_mis_count bigint;
    v_s_immune numeric;
    v_donor_age int;
    v_egs_score numeric;
    v_final_score numeric;
BEGIN
    -- Get medical urgency status value
    SELECT CASE 
               WHEN c.med_urgency = 'Status 1A' THEN 5
               WHEN c.med_urgency = 'Status 1B' THEN 4
               WHEN c.med_urgency = '2' THEN 3
               WHEN c.med_urgency = '3' THEN 2
               ELSE 1
           END,
           COALESCE((STRING_TO_ARRAY(c.wait_time, ' '))[1]::int / 365.0, 0),
           COALESCE(cm.hla_mis_count, 0),
           CASE WHEN UPPER(COALESCE(cm.blood_compat, '')) = 'COMPATIBLE' THEN 1.0 ELSE 0.0 END,
           COALESCE((STRING_TO_ARRAY(d.age_count, ' '))[1]::int, 0)
    INTO v_status_medical, v_r_wait, v_hla_mis_count, v_i_abo, v_donor_age
    FROM transplant_matching t
    LEFT JOIN clinical c ON t.recip_ref_reg = c.clin_recip_registry
    LEFT JOIN compatibility_metrics cm ON t.match_rec_registry = cm.match_comp_registry
    LEFT JOIN demographics d ON t.donor_ref_reg = d.contrib_registry
    WHERE t.match_rec_registry = p_match_id;

    -- Patient Urgency Score: S_urgency = 0.7 * Status_medical + 0.3 * R_wait
    v_s_urgency := 0.7 * v_status_medical + 0.3 * v_r_wait;

    -- Immunological Compatibility Score: S_immune = 0.6 * I_ABO + 0.4 * (1 - S_mismatch/6)
    v_s_immune := 0.6 * v_i_abo + 0.4 * (1.0 - v_hla_mis_count / 6.0);

    -- Expected Graft Survival Score: EGS = 1 / (1 + e^(-(-0.5 + 1.5 * S_immune - 0.02 * Age_donor)))
    v_egs_score := 1.0 / (1.0 + exp(-(-0.5 + 1.5 * v_s_immune - 0.02 * v_donor_age)));

    -- Composite Allocation Score: S_allocation = 0.5 * S_urgency + 0.25 * S_immune + 0.25 * EGS
    v_final_score := 0.5 * v_s_urgency + 0.25 * v_s_immune + 0.25 * v_egs_score;

    RETURN v_final_score;
END;
$$ LANGUAGE plpgsql;

