CREATE OR REPLACE FUNCTION calculate_composite_allocation_score(p_match_id text) RETURNS numeric AS $$
DECLARE
    v_urgency numeric;
    v_immune numeric;
    v_egs numeric;
BEGIN
    SELECT INTO v_urgency
        0.7 * CASE WHEN c.med_urgency = 'Status 1A' THEN 5 WHEN c.med_urgency = 'Status 1B' THEN 4 WHEN c.med_urgency = '2' THEN 3 WHEN c.med_urgency = '3' THEN 2 ELSE 1 END
        + 0.3 * COALESCE(CAST((STRING_TO_ARRAY(c.wait_time, ' '))[1] AS int), 0) / 365.0
    FROM transplant_matching t
    JOIN clinical c ON t.recip_ref_reg = c.clin_recip_registry
    WHERE t.match_rec_registry = p_match_id;

    SELECT INTO v_immune
        0.6 * CASE WHEN UPPER(cm.blood_compat) = 'COMPATIBLE' THEN 1.0 ELSE 0.0 END
        + 0.4 * (1.0 - COALESCE(cm.hla_mis_count, 0) / 6.0)
    FROM transplant_matching t
    JOIN compatibility_metrics cm ON t.match_rec_registry = cm.match_comp_registry
    WHERE t.match_rec_registry = p_match_id;

    SELECT INTO v_egs
        1.0 / (1.0 + exp(-(-0.5 + 1.5 * v_immune - 0.02 * CAST((STRING_TO_ARRAY(d.age_count, ' '))[1] AS int))))
    FROM transplant_matching t
    JOIN demographics d ON t.donor_ref_reg = d.contrib_registry
    WHERE t.match_rec_registry = p_match_id;

    RETURN ROUND(CAST(0.5 * v_urgency + 0.25 * v_immune + 0.25 * v_egs AS numeric), 4);
END;
$$ LANGUAGE plpgsql;
